INSERT OR REPLACE INTO claims (id, label) VALUES ('menh_nhom_tu_phu_vu_tuong', 'nhóm “hành động có lý luận” (Tử – Phủ – Vũ – Tướng)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('menh_nhom_sat_pha_liem_tham', 'nhóm “hành động mạnh mẽ” (Sát – Phá – Liêm – Tham)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('menh_nhom_co_nguyet_dong_luong', 'nhóm “lý luận thuần túy” (Cơ – Nguyệt – Đồng – Lương)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('menh_nhom_cu_nhat_nguyet', 'nhóm “lý luận thực hành” (Cự – Nhật – Nguyệt)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('huong_cong_chuc', 'khuynh hướng làm công, công chức');
INSERT OR REPLACE INTO claims (id, label) VALUES ('nhan_tu_thich_tu_hanh', 'tính nhân từ và thiên về đời sống tu hành');
INSERT OR REPLACE INTO claims (id, label) VALUES ('thich_ban_luan_muu_tri', 'thích bàn luận, mưu trí');
INSERT OR REPLACE INTO claims (id, label) VALUES ('co_luong_cat_tinh_thuan', 'thuận lợi về tài lộc, địa vị (khi có cát tinh hội)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('vo_thuat_hoac_tu_hanh_phieu_bat', 'nghiêng về võ thuật hoặc đời sống tu hành, di chuyển nhiều');
INSERT OR REPLACE INTO claims (id, label) VALUES ('tu_vi_thanh_cach', 'việc Tử Vi thành cách (cần Tam Hóa, ngại Tứ Sát và Không Kiếp)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('cach_sat_pha_tham', 'cấu trúc Sát – Phá – Tham trong tam phương');
INSERT OR REPLACE INTO claims (id, label) VALUES ('nhat_chu_co_can', 'Nhật Chủ có căn trong các địa chi');
INSERT OR REPLACE INTO claims (id, label) VALUES ('co_tot_thong_minh_muu_tri', 'khuynh hướng thông minh, nhiều mưu trí, tính nhân hậu từ thiện, đời sống khá giả (theo Thiên Cơ ở vị trí miếu/vượng/đắc tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('co_ham_kem_nhanh_van_du_an', 'khuynh hướng kém nhanh nhạy hơn nhưng vẫn có tài, đủ ăn đủ mặc và sống lâu (theo Thiên Cơ ở vị trí hãm tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('duong_tot_thong_minh_nhan_hau', 'khuynh hướng thông minh, cương nghị, nhân hậu (nam mệnh; sinh ban ngày thì thuận hơn) (theo Thái Dương ở vị trí miếu/vượng/đắc tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('duong_ham_ngang_gan_vat_va', 'khuynh hướng tính ương gàn, kém bền chí, đầu đời vất vả, về sau mới khá (theo Thái Dương ở vị trí hãm tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('vu_tot_chi_lon_kinh_doanh', 'khuynh hướng thông minh, chí lớn, có óc kinh doanh, thường thành đạt muộn sau khoảng 30 tuổi (theo Vũ Khúc ở vị trí miếu/vượng/đắc tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('vu_ham_lao_dao_tai_danh', 'khuynh hướng lao đao về tiền bạc và danh vọng, đời nhiều vất vả (theo Vũ Khúc ở vị trí hãm tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('dong_tot_nhan_hau_hay_doi', 'khuynh hướng nhân hậu, hay thay đổi công việc và nơi ở, thường được hưởng sung túc và thọ (theo Thiên Đồng ở vị trí miếu/vượng/đắc tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('dong_ham_nong_can_kham_kho', 'khuynh hướng suy nghĩ nông cạn, thích ăn chơi, lo toan nhiều về sinh kế (theo Thiên Đồng ở vị trí hãm tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('liem_tot_thang_than_nghiem_nghi', 'khuynh hướng thẳng thắn, nghiêm nghị, tính nóng, đời khá giả và thọ (theo Liêm Trinh ở vị trí miếu/vượng/đắc tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('liem_ham_khac_nghiet_lo_toan', 'khuynh hướng khắc nghiệt, nhiều toan tính, có óc kinh doanh và khéo kỹ nghệ nhưng cả đời lo toan vất vả (theo Liêm Trinh ở vị trí hãm tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('am_tot_hien_hoa_van_chuong', 'khuynh hướng hiền hòa nhã nhặn, từ tâm, thích văn chương mỹ thuật, thường được giàu sang và sống lâu (theo Thái Âm ở vị trí miếu/vượng/đắc tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('am_ham_uong_nganh_ngam_vinh', 'khuynh hướng tính ương ngạnh, thích ngâm vịnh, ít tham danh lợi, việc đời thường không vừa ý (theo Thái Âm ở vị trí hãm tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('tham_tot_hieu_thang_hoat_dong', 'khuynh hướng tính trung hậu nhưng tự đắc, hiếu thắng, thích hoạt động, tham vọng lớn, có óc kinh doanh; thành đạt sau 30 tuổi (theo Tham Lang ở vị trí miếu/vượng/đắc tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('tham_ham_yem_the_tu_hanh', 'khuynh hướng dễ yếm thế, làm gì cũng gặp trắc trở, thiên về đời sống tu hành mới yên (theo Tham Lang ở vị trí hãm tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('cu_tot_thong_minh_ngon_ngu', 'khuynh hướng thông minh, nhiều mưu trí, xét đoán giỏi, lời lẽ sắc sảo, thường khá giả (theo Cự Môn ở vị trí miếu/vượng/đắc tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('cu_ham_gian_xao_da_nghi', 'khuynh hướng kém sáng suốt, khắc nghiệt, đa nghi, hay nói khoác, ít thuận lợi giao thiệp (theo Cự Môn ở vị trí hãm tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('tuong_tot_uy_nghi_don_hau', 'khuynh hướng uy nghi, đôn hậu, thông minh, thích ăn ngon mặc đẹp, thường hưởng vinh hoa phúc thọ (theo Thiên Tướng ở vị trí miếu/vượng/đắc tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('luong_tot_khoan_hoa_tho', 'khuynh hướng thanh tú, khoan hòa, hưởng thọ; có văn tinh hội thì phú quý và có uy quyền (theo Thiên Lương ở vị trí miếu/vượng/đắc tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('luong_ham_phong_dang_phieu_luu', 'khuynh hướng kém thông minh, thích phóng đãng phiêu lưu, hay đổi chí hướng, bôn ba vất vả (theo Thiên Lương ở vị trí hãm tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('sat_tot_dung_manh_muu_co', 'khuynh hướng dũng mãnh, có mưu cơ, được nhiều người tin phục, giàu sang nhưng đời thường thăng trầm (theo Thất Sát ở vị trí miếu/vượng/đắc tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('sat_ham_hung_bao_khoac_lac', 'khuynh hướng tính hung hãn, hay khoa trương, đời nhiều va vấp (theo Thất Sát ở vị trí hãm tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('pha_tot_cuong_nghi_tu_dac', 'khuynh hướng thông minh, cương nghị, can đảm, thích hoạt động; đời thăng trầm, tiền bạc tụ tán bất thường (theo Phá Quân ở vị trí miếu/vượng/đắc tại cung Mệnh)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_lam_thap_than_giáp', 'tính cách thường được mô tả là tiêu xài mạnh tay, kiếm được cũng tiêu được, không so đo hơn thiệt cá nhân, tự chủ và ít dựa dẫm (bảng 日干临十神)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_ngu_hanh_giáp', 'tính cách thường được mô tả là có năng lực tổ chức, cương cường tự nghiêm khắc, có tài lãnh đạo, được nhiều người tin cậy (bảng 日干五行)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_lam_thap_than_ất', 'tính cách thường được mô tả là tiêu nhiều nhưng có tính toán, để ý hơn thiệt và lợi ích, một lòng nghĩ đến tiền của (bảng 日干临十神)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_ngu_hanh_ất', 'tính cách thường được mô tả là bề ngoài mềm yếu cẩn trọng nhưng trong lòng cố chấp, giữ nếp cũ, tình cảm dễ tổn thương (bảng 日干五行)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_lam_thap_than_bính', 'tính cách thường được mô tả là tính nóng vội, thẳng thắn, dễ vướng thị phi, tâm cao khí ngạo, hành xử phóng túng (bảng 日干临十神)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_ngu_hanh_bính', 'tính cách thường được mô tả là lịch thiệp, đôn hậu, nhiệt tình và hoạt bát cởi mở nhưng thiếu kiên tâm, dễ bị hiểu lầm là thích phô trương (bảng 日干五行)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_lam_thap_than_đinh', 'tính cách thường được mô tả là cẩn trọng chu đáo, tích cực tiến thủ, chín chắn thành thật, tuân phép công, có trách nhiệm (bảng 日干临十神)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_ngu_hanh_đinh', 'tính cách thường được mô tả là ngoài mềm trong tiến, tư duy kín đáo, lễ độ, ngại trắc trở, thắng được mà khó bại (bảng 日干五行)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_lam_thap_than_mậu', 'tính cách thường được mô tả là khôn vặt, lòng dạ hẹp, nhiều tính toán trong lòng, đa nghi, dễ hành động theo tình cảm (bảng 日干临十神)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_ngu_hanh_mậu', 'tính cách thường được mô tả là thành thật dày dặn, giỏi giao tiếp, thích chưng diện, thiếu chủ kiến, quan hệ không bền, hiếu thắng (bảng 日干五行)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_lam_thap_than_kỷ', 'tính cách thường được mô tả là nhân từ rộng lượng, lao tâm nhiều, hay lo nghĩ nhưng đối đãi người khoan dung (bảng 日干临十神)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_ngu_hanh_kỷ', 'tính cách thường được mô tả là tâm tế, có quy củ, độ lượng nhỏ, hay đa nghi và ghen ghét, hiếu thắng (bảng 日干五行)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_lam_thap_than_canh', 'tính cách thường được mô tả là nhiều bạn bè, ý chí kiên cường, thẳng thắn tự trọng, đoàn kết, hào sảng (bảng 日干临十神)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_ngu_hanh_canh', 'tính cách thường được mô tả là trọng tiền của, hơi có văn tài, giỏi kinh tế và xử lý công việc, coi trọng hưởng thụ vật chất (bảng 日干五行)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_lam_thap_than_tân', 'tính cách thường được mô tả là cứng nhắc cố chấp, hay bênh bất bình, dễ vướng thị phi, tiêu xài lớn, đời nhiều lo toan (bảng 日干临十神)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_ngu_hanh_tân', 'tính cách thường được mô tả là thiếu sức hấp dẫn, ngoan cố, nhưng thông minh và gỡ được nhiều khó khăn (bảng 日干五行)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_lam_thap_than_nhâm', 'tính cách thường được mô tả là khí chất cao nhã, tư duy thoát tục, phản ứng nhanh, đa tài đa nghệ (bảng 日干临十神)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_ngu_hanh_nhâm', 'tính cách thường được mô tả là biết đoàn kết và thuyết phục người, tính nóng, độ lượng lớn, dựa vào sức tự nhiên, cá tính hay thay đổi và đôi khi thờ ơ (bảng 日干五行)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_lam_thap_than_quý', 'tính cách thường được mô tả là không chịu ràng buộc, kiêu ngạo, thích mơ mộng và thể hiện mình, hành xử kín đáo khó đoán, dễ gặp trắc trở (bảng 日干临十神)');
INSERT OR REPLACE INTO claims (id, label) VALUES ('bt_ri_gan_ngu_hanh_quý', 'tính cách thường được mô tả là chính trực liêm khiết, cần mẫn, gặp nghịch cảnh vẫn mở được đường, có sức sống và chịu khổ giỏi (bảng 日干五行)');
