INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.05.NOTICE', 'health', 0, '{"slot":"sensitive.health","truthy":true}', 'he_thong', 'notice', '["Lưu ý trước khi đọc: Tử Vi nói về thể trạng bằng ngôn ngữ biểu tượng truyền thống; phần này không thay thế chẩn đoán y khoa và không dùng để quyết định việc chữa trị."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.05.NOTICE', 'finance', 1, '{"slot":"sensitive.finance","truthy":true}', 'he_thong', 'notice', '["Lưu ý trước khi đọc: các nhận định về tiền bạc và tài sản ở đây là cách đọc biểu tượng của sách, không phải lời khuyên cho một quyết định tài chính nào."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.05.NOTICE', 'relationships', 2, '{"slot":"sensitive.relationships","truthy":true}', 'he_thong', 'notice', '["Lưu ý trước khi đọc: các câu về hôn nhân và gia đình là cách đọc biểu tượng; quyết định trong các mối quan hệ thuộc về chính mình và những người trong cuộc, không thuộc về lá số."]', '[]', NULL);
