INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.10.FRAME', 'scope', 0, '{"all":[{"slot":"f.role","truthy":true},{"not":{"slot":"section.multi","truthy":true}}]}', 'sach', 'intro', '["Chương này đọc {chapter.scope}, trước hết qua cung {f.name} — cung mà Khảo Luận dành cho {f.role} ({f.role_cite}).","Điểm xuất phát là cung {f.name}: theo Khảo Luận, đây là nơi nói về {f.role} ({f.role_cite}), và cũng là nơi chương này đọc {chapter.scope}."]', '["{f.role_cite}"]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.10.FRAME', 'scope_multi', 1, '{"all":[{"slot":"f.role","truthy":true},{"slot":"section.multi","truthy":true}]}', 'sach', 'intro', '["Cung {f.name} nói về {f.role} ({f.role_cite})."]', '["{f.role_cite}"]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.10.FRAME', 'config', 2, '{"not":{"slot":"f.no_major","truthy":true}}', 'tinh_toan', 'intro', '["Trên lá số này, {f.name} an tại {f.where} với {f.majors_dig}{?f.sat|, có thêm sát tinh {f.sat}}{?f.cat|, có {f.cat}}{?f.hoa|, mang {f.hoa}}{?f.tt|, và gặp {f.tt}}.","{f.name} an tại {f.where}; chính tinh trong cung là {f.majors_dig}{?f.sat|, đi cùng {f.sat}}{?f.cat|, có {f.cat}}{?f.hoa|, mang {f.hoa}}{?f.tt|, lại gặp {f.tt}}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.10.FRAME', 'config_vcd', 3, '{"slot":"f.no_major","truthy":true}', 'tinh_toan', 'intro', '["{f.name} an tại {f.where} và không có chính tinh{?f.minor|, chỉ có {f.minor}}{?f.tt|, gặp {f.tt}}; khi cung vô chính diệu, bản luận đọc thêm chính tinh của cung đối diện là {opp.name} ({opp.majors_dig})."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.10.FRAME', 'triad', 4, '{"not":{"slot":"section.multi","truthy":true}}', 'tinh_toan', 'intro', '["Cung này không được đọc tách rời: hai cung tam hợp là {triad.b} ({triad.b_majors}{?triad.b_notable|, có {triad.b_notable}}) và {triad.a} ({triad.a_majors}{?triad.a_notable|, có {triad.a_notable}}), còn cung xung chiếu là {opp.name} ({opp.majors_dig}{?opp.notable|, có {opp.notable}}).","Theo phép tam phương tứ chính, {f.name} được xét cùng {triad.b} ({triad.b_majors}{?triad.b_notable|, có {triad.b_notable}}), {triad.a} ({triad.a_majors}{?triad.a_notable|, có {triad.a_notable}}) và cung đối diện {opp.name} ({opp.majors_dig}{?opp.notable|, có {opp.notable}})."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.10.FRAME', 'than_focus', 5, '{"slot":"than.is_focus","truthy":true}', 'tinh_toan', 'intro', '["Thân cư ngay tại {f.name}, nên cung này vừa là nơi đọc {topic} vừa là cung Thân."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.10.FRAME', 'than_opp', 6, '{"slot":"than.is_opp","truthy":true}', 'tinh_toan', 'intro', '["Cung đối diện {opp.name} cũng là nơi Thân cư, nên cung Thân nằm ngay trên trục đối chiếu của {topic}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.10.FRAME', 'than_triad', 7, '{"slot":"than.in_triad","truthy":true}', 'tinh_toan', 'intro', '["Thân cư ở {than.palace}, một trong hai cung tam hợp của {f.name}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.10.FRAME', 'profiles', 8, '{"all":[{"slot":"profiles","truthy":true},{"not":{"slot":"section.multi","truthy":true}}]}', 'sach', 'ground', '["Trước khi xét vị trí, nên nhớ nền nghĩa mà Thực Hành gán cho chính tinh ở đây: {profiles} ({profiles.cite}).","Thực Hành mở đầu phần mỗi sao bằng nền nghĩa của nó: {profiles} ({profiles.cite}); các câu theo vị trí bên dưới đứng trên nền ấy."]', '["{profiles.cite}"]', NULL);
INSERT OR REPLACE INTO content_modules (id, chapter, role, version, status, title, when_json, evidence_json, slots_json, author, layout_json) VALUES ('S.30.THEMES', '*', 'factor', 1, 'draft', 'Chủ đề', NULL, NULL, NULL, 'Claude (biên tập máy, chờ chuyên gia duyệt)', '{"order":30,"each":"themes"}');
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'open_first', 0, '{"all":[{"slot":"t.first","truthy":true},{"not":{"slot":"t.np_is_topic","truthy":true}}]}', 'he_thong', 'frame', '["Điểm tựa rõ nhất của {topic} trên lá số này là {t.np}, và căn cứ của nó nằm ở {t.where}.","Nếu phải chọn một trục để đọc {topic}, đó là {t.np}: căn cứ nằm ở {t.where}.","Chủ đề nổi lên trước tiên khi đọc {topic} là {t.np}, đứng trên {t.where}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'open_topic', 1, '{"all":[{"slot":"t.first","truthy":true},{"slot":"t.np_is_topic","truthy":true}]}', 'he_thong', 'frame', '["Về {topic}, căn cứ rõ nhất nằm ở {t.where}.","Với {topic}, mọi thứ bắt đầu từ {t.where}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'open_next', 2, '{"slot":"t.next","truthy":true}', 'he_thong', 'frame', '["Trục {t.ord} là {t.np}, đọc từ {t.where}.","Bên cạnh đó còn {t.np}; căn cứ nằm ở {t.where}.","Một mạch khác chạy song song là {t.np}, với căn cứ ở {t.where}.","Tiếp theo là {t.np}, đứng trên {t.where}.","Lá số còn cho thấy {t.np}, qua {t.where}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'open_neg', 3, '{"slot":"t.neg","truthy":true}', 'he_thong', 'frame', '["Phía cần cân nhắc là {t.np}, và dấu hiệu nằm ở {t.where}.","Mặt cần để ý là {t.np}; nó đến từ {t.where}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'lead', 4, NULL, 'sach', 'claim', '["{t.lead_books} ghi {t.lead_quote} cho trường hợp {t.lead_cond} ({t.lead_cite}).","Với {t.lead_cond}, {t.lead_books} cho là {t.lead_quote} ({t.lead_cite}).","Câu sách trực tiếp là của {t.lead_books}: khi {t.lead_cond} thì {t.lead_quote} ({t.lead_cite}).","Câu sách cho chỗ này là của {t.lead_books}: {t.lead_quote}, khi {t.lead_cond} ({t.lead_cite}).","Ở đây, {t.lead_books} ghi {t.lead_quote} ({t.lead_cite}), với điều kiện {t.lead_cond}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'dep', 5, '{"slot":"t.dep","truthy":true}', 'dieu_kien', 'condition', '["Câu ấy đứng được là nhờ {t.dep}, nên đây là chỗ {t.dep_from} nối thẳng vào {t.dep_palaces}.","Điều kiện của câu này có {t.dep}: nhận định ở {t.dep_from} vì thế gắn liền với {t.dep_palaces}.","Câu này chỉ đứng được vì {t.dep}; nhận định ở {t.dep_from} do đó gắn với {t.dep_palaces}.","Điểm cần thấy là điều kiện của nó nằm một phần ngoài {t.dep_from}: {t.dep}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'dep_again', 6, '{"slot":"t.dep_again","truthy":true}', 'dieu_kien', 'condition', '["Câu này cũng dựa vào {t.dep_again}, như đã nói ở trên.","Điều kiện của nó cũng nhờ {t.dep_again}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'lead_shared', 7, '{"slot":"t.lead_shared","truthy":true}', 'dieu_kien', 'interaction', '["Đó là {t.lead_shared} cách nói cho cùng một tổ hợp sao, nên chúng chỉ được tính như một căn cứ.","Các câu ấy cùng đứng trên một dữ kiện, nên dù có {t.lead_shared} câu, đây vẫn là một căn cứ."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'lead_more', 8, '{"slot":"t.lead_more_grounds","truthy":true}', 'sach', 'claim', '["Cùng nhận định ấy, sách còn ghi ở chỗ khác: {t.lead_more_grounds}.","Nhận định này không đứng một mình: {t.lead_more_grounds}.","Một nguồn khác đi đến cùng chỗ: {t.lead_more_grounds}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'more', 9, '{"slot":"t.more","truthy":true}', 'sach', 'claim', '["Cùng chiều với đó, {t.more}.","Điều này được củng cố thêm: {t.more}.","Thêm một căn cứ cùng hướng: {t.more}.","Đi cùng nhận định ấy, {t.more}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'mod_strong', 10, '{"slot":"t.mod_strong","truthy":true}', 'sach', 'condition', '["Độ sáng của sao ủng hộ cách đọc này: {t.mod_dignity}, mà Khảo Luận nhắc rằng chính tinh đắc địa thì tốt (Khảo Luận tr.233).","Về độ sáng, {t.mod_dignity}; theo nguyên tắc Khảo Luận nêu, chính tinh đắc địa thì tốt (Khảo Luận tr.233), nên phần thuận có điều kiện để hiện ra."]', '["KL p.233"]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'mod_weak', 11, '{"slot":"t.mod_weak","truthy":true}', 'sach', 'condition', '["Cần trừ hao phần thuận vì độ sáng: {t.mod_dignity}, mà Khảo Luận nhắc rằng chính tinh hãm địa thì xấu (Khảo Luận tr.233)."]', '["KL p.233"]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'mod_mid', 12, '{"slot":"t.mod_mid","truthy":true}', 'tinh_toan', 'condition', '["Về độ sáng, {t.mod_dignity}; ở mức bình, sao không đắc mà cũng không hãm."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'mod_fact', 13, '{"slot":"t.mod_fact","truthy":true}', 'tinh_toan', 'condition', '["Về độ sáng, {t.mod_dignity}.","Độ sáng của sao ở đây: {t.mod_dignity}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'counter_same_book', 14, '{"all":[{"slot":"t.counter","truthy":true},{"slot":"t.same_book","truthy":true}]}', 'sach', 'contrast', '["Nhưng chính {t.same_book} cũng ghi chiều ngược lại: {t.counter_quote} khi {t.counter_cond} ({t.counter_cite}), và điều kiện ấy có mặt trên lá số.","Có điều, {t.same_book} tự đặt cạnh đó một câu kéo xuống: {t.counter_quote} cho trường hợp {t.counter_cond} ({t.counter_cite}).","Cũng trong {t.same_book}, một câu khác đi theo chiều ngược: {t.counter_quote} khi {t.counter_cond} ({t.counter_cite}).","{t.same_book} không chỉ nói một chiều: với {t.counter_cond}, sách ghi {t.counter_quote} ({t.counter_cite}).","Ngay trong {t.same_book} đã có câu hãm bớt: {t.counter_quote}, ứng với {t.counter_cond} ({t.counter_cite})."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'counter', 15, '{"all":[{"slot":"t.counter","truthy":true},{"not":{"slot":"t.same_book","truthy":true}}]}', 'sach', 'contrast', '["Tuy vậy, {t.counter}.","Mặt kéo ngược lại cũng có: {t.counter}.","Nhưng không phải mọi câu đều cùng chiều: {t.counter}.","Ở chiều ngược lại, {t.counter}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'counter_more', 16, '{"slot":"t.counter_more","truthy":true}', 'sach', 'contrast', '["Ý hạn chế ấy không chỉ ở một sách: {t.counter_more}.","Cùng ý hạn chế ấy, {t.counter_more}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'counter2', 17, '{"slot":"t.counter2","truthy":true}', 'sach', 'contrast', '["Thêm một điều kiện cùng hướng kéo xuống: {t.counter2}.","Cùng phía hạn chế ấy, {t.counter2}.","Một câu nữa cũng kéo xuống: {t.counter2}.","Phía hạn chế còn thêm: {t.counter2}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'counter_rest', 18, '{"slot":"t.counter_rest","truthy":true}', 'sach', 'contrast', '["Cũng theo chiều kéo xuống ấy, {t.counter_rest}.","Ngoài ra còn {t.counter_rest}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'resolve_qualified', 19, '{"slot":"t.k_qualified","truthy":true}', 'dieu_kien', 'interaction', '["Hai chiều này không loại trừ nhau: phía thuận nói tiềm năng của tổ hợp sao, còn phía hạn chế nói điều kiện đang có mặt ({t.counter_cond}); đọc chung, {t.short} có nền nhưng không trọn vẹn.","Đặt hai câu cạnh nhau, câu thuận vẫn đứng như mô tả tiềm năng của {?t.shared_stars|{t.shared_stars} trong }tổ hợp này, còn {t.counter_cond} là phần điều chỉnh mức độ; {t.short} vì thế có thật nhưng không đi một mạch."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'resolve_relation', 20, '{"slot":"t.k_relation","truthy":true}', 'he_thong', 'interaction', '["Đọc chung hai mặt ấy: {t.k_relation}.","Ghép hai câu lại, điều hiện ra là {t.k_relation}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'resolve_both', 21, '{"slot":"t.k_both","truthy":true}', 'dieu_kien', 'interaction', '["Hai nhận định đứng trên những dữ kiện khác nhau ({t.lead_cond}, và {t.counter_cond}), cả hai đều thỏa trên lá số, nên cả hai chiều cùng có mặt; sách không nói chiều nào mạnh hơn.","Vì mỗi câu dựa trên một dữ kiện riêng và lá số thỏa cả hai, bản luận giữ cả hai chiều thay vì chọn một.","Không câu nào bao trùm câu kia: mỗi câu đứng trên dữ kiện riêng ({t.lead_cond}, và {t.counter_cond}) và cả hai cùng thỏa, nên bức tranh ở đây có hai chiều.","Mỗi câu đứng trên một dữ kiện khác, và lá số thỏa cả hai; vì vậy cả hai chiều được giữ, sách không nói chiều nào nặng hơn."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'resolve_refine', 22, '{"slot":"t.k_refine","truthy":true}', 'dieu_kien', 'interaction', '["Câu hạn chế có điều kiện cụ thể hơn và lá số thỏa đúng điều kiện ấy ({t.counter_cond}), nên nó thu hẹp chứ không xóa nhận định thuận."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.30.THEMES', 'back', 23, '{"slot":"t.back_self","truthy":true}', 'dieu_kien', 'interaction', '["Câu “{t.back_self}” ở đây đi ngược với “{t.back_other}” đã nêu ở {t.back_where}{?t.back_conds|; mỗi câu đứng trên một dữ kiện riêng ({t.back_conds})} và cả hai cùng thỏa, nên bản luận giữ cả hai thay vì để câu này xóa câu kia.","Nên đọc “{t.back_self}” cạnh “{t.back_other}” ở {t.back_where}: hai câu kéo về hai phía{?t.back_conds|, đứng trên hai dữ kiện khác nhau ({t.back_conds})}, và sách không nói câu nào nặng hơn.","“{t.back_self}” và “{t.back_other}” (ở {t.back_where}) không cùng chiều; cả hai điều kiện đều có mặt trên lá số, nên cả hai được giữ và không câu nào được coi là kết luận riêng."]', '[]', NULL);
INSERT OR REPLACE INTO content_modules (id, chapter, role, version, status, title, when_json, evidence_json, slots_json, author, layout_json) VALUES ('S.38.REST', '*', 'factor', 1, 'draft', 'Những điểm phụ', '{"slot":"rest","truthy":true}', NULL, NULL, 'Claude (biên tập máy, chờ chuyên gia duyệt)', '{"order":38}');
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.38.REST', 'rest', 0, NULL, 'sach', 'claim', '["Ngoài các trục trên, lá số còn có {rest}; những điểm này ít căn cứ hơn nên chỉ được nêu ngắn."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.38.REST', 'pair', 1, '{"slot":"rest.pair_a","truthy":true}', 'dieu_kien', 'interaction', '["Trong số đó, “{rest.pair_a}” và “{rest.pair_b}” kéo về hai phía; điều kiện của cả hai đều có mặt, nên cả hai được ghi lại và không câu nào được coi là kết luận riêng.","Lưu ý rằng “{rest.pair_a}” và “{rest.pair_b}” ngược chiều nhau; sách không nói câu nào nặng hơn, nên cả hai cùng được giữ."]', '[]', NULL);
INSERT OR REPLACE INTO content_modules (id, chapter, role, version, status, title, when_json, evidence_json, slots_json, author, layout_json) VALUES ('S.45.CROSS', '*', 'cross', 1, 'retired', 'Mối nối với các cung khác', '{"list":"cross"}', NULL, NULL, 'Claude (biên tập máy, chờ chuyên gia duyệt)', '{"order":45}');
