INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.45.CROSS', 'item', 0, NULL, 'sach', 'claim', '["{x.books} ghi cho {x.from} câu “{x.quote}” ({x.cite}){?x.deps|, và câu này chỉ đứng được vì {x.deps}}.","Từ {x.from}, {x.books} còn ghi “{x.quote}” ({x.cite}){?x.deps|; điều kiện của câu ấy có {x.deps}}."]', '[]', '{"each":"cross","followups":["Tương tự, {x.books} ghi cho {x.from} câu “{x.quote}” ({x.cite}){?x.deps|, câu này cần {x.deps}}.","{x.from} còn có câu “{x.quote}” của {x.books} ({x.cite}){?x.deps|, đứng trên {x.deps}}."]}');
INSERT OR REPLACE INTO content_modules (id, chapter, role, version, status, title, when_json, evidence_json, slots_json, author, layout_json) VALUES ('S.50.ENV', '*', 'cross', 1, 'draft', 'Bối cảnh từ cung {env.name}', NULL, NULL, NULL, 'Claude (biên tập máy, chờ chuyên gia duyệt)', '{"order":50,"each":"env_themes","merge":true}');
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.50.ENV', 'open', 0, '{"slot":"t.first","truthy":true}', 'he_thong', 'frame', '["Bối cảnh bên ngoài được đọc ở {env.name}{?env.is_opp|, cung đối diện với {f.name}}.","Nhìn sang {env.name}{?env.is_opp|, cung đối diện với {f.name}}, bối cảnh bên ngoài hiện ra theo nhiều mặt."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.50.ENV', 'lead', 1, NULL, 'sach', 'claim', '["{t.lead_books} ghi {t.lead_quote} khi {t.lead_cond} ({t.lead_cite}) — tức là {t.np}.","Với {t.lead_cond}, {t.lead_books} cho là {t.lead_quote} ({t.lead_cite}), một nét về {t.short}."]', '[]', '{"followups":["Bên cạnh đó, {t.lead_books} ghi {t.lead_quote} khi {t.lead_cond} ({t.lead_cite}).","Cũng ở {env.name}, {t.lead_books} cho là {t.lead_quote} khi {t.lead_cond} ({t.lead_cite}).","Ngoài ra, với {t.lead_cond}, {t.lead_books} ghi {t.lead_quote} ({t.lead_cite})."]}');
