INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.50.ENV', 'counter', 3, '{"slot":"t.counter","truthy":true}', 'sach', 'contrast', '["Đặt cạnh đó, {t.counter}.","Nhưng {t.counter}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.50.ENV', 'counter_more', 4, '{"slot":"t.counter_more","truthy":true}', 'sach', 'contrast', '["Ý hạn chế ấy không chỉ ở một sách: {t.counter_more}.","Cùng ý hạn chế ấy, {t.counter_more}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.50.ENV', 'resolve_both', 5, '{"any":[{"slot":"t.k_both","truthy":true},{"slot":"t.k_qualified","truthy":true},{"slot":"t.k_refine","truthy":true}]}', 'dieu_kien', 'interaction', '["Hai câu đứng trên những dữ kiện khác nhau ({t.lead_cond}, và {t.counter_cond}) và cùng thỏa, nên cả hai mặt cùng có mặt.","Vì mỗi câu dựa trên một dữ kiện riêng và lá số thỏa cả hai, bản luận giữ cả hai mặt."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.50.ENV', 'resolve_relation', 6, '{"slot":"t.k_relation","truthy":true}', 'he_thong', 'interaction', '["Đọc chung: {t.k_relation}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.50.ENV', 'back', 7, '{"slot":"t.back_self","truthy":true}', 'dieu_kien', 'interaction', '["Đặt bối cảnh này cạnh phần trước: “{t.back_self}” không cùng chiều với “{t.back_other}” ({t.back_where}); cả hai điều kiện đều thỏa nên cả hai được giữ.","Bối cảnh ấy kéo ngược với một câu đã nêu: “{t.back_self}” so với “{t.back_other}” ở {t.back_where}; sách không nói bên nào nặng hơn."]', '[]', NULL);
