INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.60.TIMING', 'dh', 0, '{"slot":"dh.focus","truthy":true}', 'tinh_toan', 'timing', '["Đại hạn đi qua cung {f.name} rơi vào khoảng {dh.focus} tuổi mụ (can {dh.focus_stem}).","Chặng mười năm của {f.name} là {dh.focus} tuổi mụ, can {dh.focus_stem}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.60.TIMING', 'stage', 1, '{"slot":"dh.focus_stage","truthy":true}', 'sach', 'timing', '["Theo cách Khảo Luận gọi tên các chặng, đó là chặng {dh.focus_stage} (Khảo Luận tr.233–236).","Khảo Luận gọi chặng ấy là {dh.focus_stage} (Khảo Luận tr.233–236)."]', '["KL pp.233-236"]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.60.TIMING', 'now', 2, '{"all":[{"slot":"dh.now","truthy":true},{"not":{"slot":"section.multi","truthy":true}}]}', 'tinh_toan', 'timing', '["Năm {year}, đương số {age} tuổi mụ và đang ở đại hạn {dh.now}{?dh.now_is_focus|, tức chính chặng của {topic}}{?dh.before|; chặng của {topic} còn ở phía trước}{?dh.passed|; chặng ấy đã đi qua}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.60.TIMING', 'readings', 3, '{"slot":"dh.focus_readings","truthy":true}', 'sach', 'timing', '["Với chặng ấy, phép đọc vận của sách cho: {dh.focus_readings}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.60.TIMING', 'readings_conflict', 4, '{"slot":"dh.focus_conflict","truthy":true}', 'dieu_kien', 'interaction', '["Các câu này ngược chiều nhau trên cùng một chặng và cùng khớp điều kiện, nên bản luận không kết luận chặng ấy đi lên hay đi xuống."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.60.TIMING', 'hoa_into', 5, '{"all":[{"slot":"hoa_into","truthy":true},{"not":{"slot":"section.multi","truthy":true}}]}', 'tinh_toan', 'timing', '["Về Tứ Hóa theo can đại hạn: {hoa_into}; bộ quy tắc chưa có câu sách cho sự giao thoa này nên ở đây chỉ ghi vị trí."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.60.TIMING', 'claims', 6, '{"slot":"timing.list","truthy":true}', 'sach', 'timing', '["Về nhịp, sách có: {timing.list}.","Những câu sách nói về thời điểm gồm: {timing.list}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.60.TIMING', 'conflict', 7, '{"slot":"timing.conflict","truthy":true}', 'dieu_kien', 'interaction', '["Hai câu này đi ngược chiều nhau — một câu đứng trên {timing.early_cond}, câu kia trên {timing.late_cond} — và cả hai đều thỏa; sách không xếp thứ tự giữa chúng, nên cả hai được giữ."]', '[]', NULL);
