INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.85.LIMITS', 'method', 0, NULL, 'he_thong', 'method', '["Các câu trong ngoặc kép là phần diễn ý ngắn của câu sách đã đối chiếu, kèm số trang để kiểm lại; chúng không phải nguyên văn."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.85.LIMITS', 'criteria', 1, '{"slot":"lim.criteria","truthy":true}', 'he_thong', 'method', '["Khi câu thuận và câu hạn chế cùng có mặt, sách không nói bên nào thắng; bản luận đặt chúng cạnh nhau theo năm tiêu chí công khai (cùng chính tinh hay không, cùng sách hay không, điều kiện bên nào cụ thể hơn, bên nào đứng trên sát tinh, mỗi bên bao nhiêu căn cứ độc lập), và đó là quy ước của hệ thống chứ không phải lời sách."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.85.LIMITS', 'scope', 2, '{"slot":"lim.scope","truthy":true}', 'dieu_kien', 'limits', '["Cùng tổ hợp {f.majors}, sách còn có những câu viết cho cung Mệnh ({lim.scope}); chúng không được áp sang {f.name} vì sách không nói cho cung này."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.85.LIMITS', 'drafts', 3, '{"slot":"lim.drafts","truthy":true}', 'dieu_kien', 'limits', '["Có {lim.drafts_n} câu bị để ngoài vì quy tắc sinh ra {lim.drafts_pron} chưa được đối chiếu đủ: {lim.drafts}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.85.LIMITS', 'thin', 4, '{"all":[{"slot":"evidence.thin","truthy":true},{"not":{"slot":"section.multi","truthy":true}},{"not":{"slot":"evidence.none","truthy":true}}]}', 'he_thong', 'limits', '["Bộ quy tắc đã đối chiếu có ít câu cho {topic} trên lá số này, nên chương ngắn; phần còn trống không được viết thêm cho đủ độ dài."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.85.LIMITS', 'empty_sections', 5, '{"all":[{"slot":"chapter.empty","truthy":true},{"slot":"section.multi","truthy":true}]}', 'he_thong', 'limits', '["Ở {chapter.empty}, lá số không kích hoạt câu sách đã đối chiếu nào, nên các cung ấy chỉ được ghi cấu hình sao, không luận."]', '[]', NULL);
INSERT OR REPLACE INTO content_modules (id, chapter, role, version, status, title, when_json, evidence_json, slots_json, author, layout_json) VALUES ('S.90.SYN', '*', 'synthesis', 1, 'draft', 'Tổng hợp', '{"slot":"section.last","truthy":true}', NULL, NULL, 'Claude (biên tập máy, chờ chuyên gia duyệt)', '{"order":90}');
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.90.SYN', 'lead', 0, '{"all":[{"slot":"syn.lead","truthy":true},{"not":{"slot":"section.multi","truthy":true}}]}', 'he_thong', 'synthesis', '["Gộp lại, trục chính của {topic} trên lá số này là {syn.lead}, đứng trên {syn.lead_where}{?syn.second|; đi kèm là {syn.second}}.","Nhìn toàn chương, {topic} xoay quanh {syn.lead}, với căn cứ ở {syn.lead_where}{?syn.second|, và bên cạnh đó là {syn.second}}."]', '[]', NULL);
