INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.90.SYN', 'counter', 2, '{"all":[{"slot":"syn.counter","truthy":true},{"not":{"slot":"section.multi","truthy":true}}]}', 'he_thong', 'synthesis', '["{?syn.qualified|Phần thuận ấy không trọn vẹn: }yếu tố kéo ngược lại là {syn.counter}{?syn.counter_where|, gắn với {syn.counter_where}}.","Điều làm bức tranh bớt một chiều là {syn.counter}{?syn.counter_where|, xoay quanh {syn.counter_where}}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('S.90.SYN', 'cross', 3, '{"all":[{"slot":"syn.cross","truthy":true},{"not":{"slot":"section.multi","truthy":true}}]}', 'he_thong', 'synthesis', '["{topic} không đứng riêng: nó còn được đọc qua {syn.cross}.","Ngoài cung chính, {topic} còn được soi qua {syn.cross}."]', '[]', NULL);
