INSERT OR REPLACE INTO content_modules (id, chapter, role, version, status, title, when_json, evidence_json, slots_json, author, layout_json) VALUES ('BT.10.FRAME', 'bat_tu', 'central', 1, 'draft', 'Tứ trụ và nhật chủ', '{"not":{"slot":"bz.none","truthy":true}}', NULL, NULL, 'Claude (biên tập máy, chờ chuyên gia duyệt)', '{"order":10}');
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('BT.10.FRAME', 'pillars', 0, NULL, 'tinh_toan', 'intro', '["Tứ trụ của lá số là trụ {bz.pillars}. Nhật chủ, tức thiên can của trụ ngày, là {bz.dm}, thuộc hành {bz.dm_el}.","Bốn trụ được tính ra là trụ {bz.pillars}; thiên can ngày {bz.dm} (hành {bz.dm_el}) là nhật chủ, điểm quy chiếu của mọi quan hệ trong Bát Tự."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('BT.10.FRAME', 'month', 1, '{"slot":"bz.dm_stage","truthy":true}', 'tinh_toan', 'intro', '["Nhật chủ sinh vào tháng {bz.month_branch}; theo vòng trường sinh, {bz.dm} ở tháng này rơi vào trạng thái {bz.dm_stage}. Tàng can của nguyệt lệnh {bz.month_branch} là {bz.month_hidden}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('BT.10.FRAME', 'gods', 2, '{"slot":"bz.stem_gods","truthy":true}', 'tinh_toan', 'intro', '["Xét theo nhật chủ, thập thần của các thiên can còn lại là: {bz.stem_gods}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('BT.10.FRAME', 'roots', 3, '{"slot":"bz.roots","truthy":true}', 'tinh_toan', 'intro', '["Nhật chủ có gốc: tàng can cùng hành {bz.dm_el} xuất hiện ở {bz.roots}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('BT.10.FRAME', 'no_root', 4, '{"slot":"bz.no_root","truthy":true}', 'tinh_toan', 'intro', '["Không chi nào trong bốn trụ tàng can cùng hành {bz.dm_el} với nhật chủ, tức nhật chủ không có gốc trong địa chi."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('BT.10.FRAME', 'elements', 5, '{"slot":"bz.missing","truthy":true}', 'tinh_toan', 'intro', '["Trên thiên can và hành chính của bốn địa chi không thấy hành {bz.missing}{?bz.hidden_only|; hành {bz.hidden_only} chỉ có mặt trong tàng can}."]', '[]', NULL);
