INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('BT.20.DM', 'dm', 0, NULL, 'sach', 'claim', '["Bát Tự Chân Tông mô tả người có nhật chủ {bz.dm} là “{r.quote}” ({r.cite}).","Với nhật chủ {bz.dm}, sách ghi: “{r.quote}” ({r.cite})."]', '[]', '{"each":"bz_dm","followups":["Bảng thứ hai của sách cho cùng nhật chủ ấy ghi thêm: “{r.quote}” ({r.cite}).","Sách còn ghi cho nhật chủ {bz.dm}: “{r.quote}” ({r.cite})."]}');
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('BT.20.DM', 'note', 1, '{"list":"bz_dm","min":2}', 'dieu_kien', 'interaction', '["Hai mô tả này đến từ hai bảng tra khác nhau của cùng một sách, đều chỉ dựa trên thiên can ngày; chúng là nét chung của mọi người cùng nhật chủ {bz.dm}, chưa xét đến các trụ khác."]', '[]', NULL);
