INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('BT.30.NAPAM', 'napam', 0, NULL, 'sach', 'claim', '["Trụ ngày {bz.day} có nạp âm {bz.napam}; theo cách sách đọc tính cách từ nạp âm trụ ngày, đó là người “{r.quote}” ({r.cite}).","Nạp âm của trụ ngày {bz.day} là {bz.napam}, và sách đọc nạp âm ấy là “{r.quote}” ({r.cite})."]', '[]', '{"each":"bz_napam"}');
