INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('BT.50.LUCK', 'luck', 0, NULL, 'tinh_toan', 'timing', '["Đại vận chạy {bz.luck_dir}, khởi vận vào khoảng {bz.luck_start}; mỗi vận kéo dài mười năm."]', '[]', NULL);
