INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('BT.50.LUCK', 'no_reading', 3, NULL, 'he_thong', 'limits', '["Bộ quy tắc Bát Tự đã đối chiếu chưa có câu sách nào đọc đại vận, nên ở đây chỉ ghi vận đang đi, không luận tốt xấu."]', '[]', NULL);
INSERT OR REPLACE INTO content_modules (id, chapter, role, version, status, title, when_json, evidence_json, slots_json, author, layout_json) VALUES ('BT.85.LIMITS', 'bat_tu', 'limits', 1, 'draft', 'Cơ sở và giới hạn', '{"not":{"slot":"bz.none","truthy":true}}', NULL, NULL, 'Claude (biên tập máy, chờ chuyên gia duyệt)', '{"order":85}');
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('BT.85.LIMITS', 'method', 0, NULL, 'he_thong', 'method', '["Các câu trong ngoặc kép là phần diễn ý của Bát Tự Chân Tông (八字真宗), ghi theo số trang PDF của bản đang lưu hành; chúng không phải nguyên văn. Phần Bát Tự được đọc riêng, không trộn với Tử Vi."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('BT.85.LIMITS', 'scope', 1, NULL, 'he_thong', 'limits', '["Chương này chưa xét vượng suy của nhật chủ, dụng thần và cách cục: các phép ấy chưa có quy tắc vừa đã đối chiếu vừa đã nối vào dữ kiện trong bản luận này, nên mọi nhận định về chúng đều bị bỏ trống thay vì đoán. Các phán đoán trực tiếp của sách về nghề nghiệp, hôn nhân, anh em (PDF tr.51–58) đã được đối chiếu nhưng chưa được nối vào hệ thống, nên cũng chưa dùng ở đây."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('BT.85.LIMITS', 'drafts', 2, '{"slot":"bz.drafts","truthy":true}', 'dieu_kien', 'limits', '["Có {bz.drafts_n} câu bị để ngoài vì quy tắc tương ứng chưa được đối chiếu đủ: {bz.drafts}."]', '[]', NULL);
INSERT OR REPLACE INTO content_modules (id, chapter, role, version, status, title, when_json, evidence_json, slots_json, author, layout_json) VALUES ('BT.90.SYN', 'bat_tu', 'synthesis', 1, 'draft', 'Tổng hợp', '{"not":{"slot":"bz.none","truthy":true}}', NULL, NULL, 'Claude (biên tập máy, chờ chuyên gia duyệt)', '{"order":90}');
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('BT.90.SYN', 'syn', 0, '{"slot":"bz.has_readings","truthy":true}', 'he_thong', 'synthesis', '["Phần Bát Tự đã đối chiếu trên lá số này gồm {bz.verified_n} câu sách, đều đọc từ trụ ngày: mô tả tính cách theo nhật chủ {bz.dm} và theo nạp âm {bz.napam}. Đó là những nét sách gán cho mọi người cùng nhật chủ hay cùng trụ ngày, nên chỉ là điểm khởi đầu; phần riêng của lá số nằm ở quan hệ giữa bốn trụ, mà bản luận chưa có quy tắc đã kiểm chứng để đọc."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('BT.90.SYN', 'none', 1, '{"not":{"slot":"bz.has_readings","truthy":true}}', 'he_thong', 'synthesis', '["Trên lá số này chưa có câu sách Bát Tự đã đối chiếu nào khớp, nên chương chỉ ghi tứ trụ và đại vận."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('BT.90.SYN', 'frame', 2, NULL, 'he_thong', 'reflection', '["Đây là cách đọc theo hệ biểu tượng truyền thống, có điều kiện, không phải lời tiên đoán."]', '[]', NULL);
INSERT OR REPLACE INTO content_modules (id, chapter, role, version, status, title, when_json, evidence_json, slots_json, author, layout_json) VALUES ('CD.15.GROUP', 'cong_danh', 'cross', 1, 'draft', 'Một trục sao giữa con người và công việc', '{"slot":"group.same","truthy":true}', NULL, NULL, 'Claude (biên tập máy, chờ chuyên gia duyệt)', '{"order":15}');
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('CD.15.GROUP', 'group', 0, NULL, 'sach', 'ground', '["Cả Mệnh ({menh.majors_dig}) lẫn Quan Lộc ({f.majors}) đều thuộc nhóm Tử – Phủ – Vũ – Tướng, nhóm mà Khảo Luận gọi là “hành động có lý luận” (Khảo Luận tr.166–167): con người và công việc nằm trên cùng một trục sao.","Mệnh ({menh.majors_dig}) và Quan Lộc ({f.majors}) cùng thuộc nhóm Tử – Phủ – Vũ – Tướng — theo Khảo Luận là nhóm “hành động có lý luận” (Khảo Luận tr.166–167) — nên cách làm việc và cách làm người ở đây cùng một chất."]', '["KL pp.166-167"]', NULL);
INSERT OR REPLACE INTO content_modules (id, chapter, role, version, status, title, when_json, evidence_json, slots_json, author, layout_json) VALUES ('DN.20.HOA', 'di_no_tat', 'factor', 1, 'draft', 'Tứ Hóa tại cung bạn bè', '{"slot":"f.hoa_notes","truthy":true}', NULL, NULL, 'Claude (biên tập máy, chờ chuyên gia duyệt)', '{"order":20}');
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('DN.20.HOA', 'hoa', 0, NULL, 'sach', 'ground', '["Cung này mang Tứ Hóa của năm sinh, và Khảo Luận ghi riêng cho vị trí ấy: {f.hoa_notes} (Khảo Luận tr.195–197)."]', '["KL pp.195-197"]', NULL);
INSERT OR REPLACE INTO content_modules (id, chapter, role, version, status, title, when_json, evidence_json, slots_json, author, layout_json) VALUES ('MT.10.FRAME', 'menh', 'central', 1, 'draft', 'Cung Mệnh và cung Thân', NULL, NULL, NULL, 'Claude (biên tập máy, chờ chuyên gia duyệt)', '{"order":10}');
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('MT.10.FRAME', 'role', 0, '{"slot":"f.role","truthy":true}', 'sach', 'intro', '["Chương này đọc {chapter.scope}, trước hết qua cung Mệnh — cung mà Khảo Luận dành cho {f.role} ({f.role_cite}).","Con người nền tảng được đọc ở cung Mệnh; theo Khảo Luận, đây là nơi nói về {f.role} ({f.role_cite})."]', '["{f.role_cite}"]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('MT.10.FRAME', 'config', 1, '{"not":{"slot":"f.no_major","truthy":true}}', 'tinh_toan', 'intro', '["Mệnh an tại {f.where} với {f.majors_dig}{?f.sat|, có sát tinh {f.sat}}{?f.cat|, có {f.cat}}{?f.hoa|, mang {f.hoa}}{?f.tt|, gặp {f.tt}}.","Cung Mệnh an tại {f.where}; chính tinh là {f.majors_dig}{?f.sat|, đi cùng {f.sat}}{?f.cat|, có {f.cat}}{?f.hoa|, mang {f.hoa}}{?f.tt|, lại gặp {f.tt}}."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('MT.10.FRAME', 'config_vcd', 2, '{"slot":"f.no_major","truthy":true}', 'tinh_toan', 'intro', '["Mệnh an tại {f.where} và không có chính tinh{?f.minor|, chỉ có {f.minor}}{?f.tt|, gặp {f.tt}}; khi Mệnh vô chính diệu, bản luận đọc thêm chính tinh của cung đối diện là {opp.name} ({opp.majors_dig})."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('MT.10.FRAME', 'cuc', 3, '{"slot":"menh.cuc_rel","truthy":true}', 'tinh_toan', 'intro', '["Cục là {menh.cuc}, bản mệnh {menh.nap_am}; quan hệ giữa cục và mệnh được ghi là “{menh.cuc_rel}”."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('MT.10.FRAME', 'triad', 4, NULL, 'tinh_toan', 'intro', '["Ba cung soi về Mệnh là {triad.b} ({triad.b_majors}{?triad.b_notable|, có {triad.b_notable}}), {triad.a} ({triad.a_majors}{?triad.a_notable|, có {triad.a_notable}}) và cung đối diện {opp.name} ({opp.majors_dig}{?opp.notable|, có {opp.notable}})."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('MT.10.FRAME', 'than_same', 5, '{"not":{"slot":"than.differs","truthy":true}}', 'tinh_toan', 'intro', '["Thân cư ngay tại Mệnh, nên con người tiên thiên và con người hậu thiên được đọc ở cùng một cung."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('MT.10.FRAME', 'than_other', 6, '{"slot":"than.differs","truthy":true}', 'tinh_toan', 'intro', '["Thân cư ở cung {than.palace} ({than.majors_dig}), nên ngoài Mệnh, các câu sách ở cung ấy cũng được tính khi đọc con người."]', '[]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('MT.10.FRAME', 'group', 7, '{"slot":"f.group","truthy":true}', 'sach', 'ground', '["Theo cách phân nhóm của Khảo Luận, chính tinh {f.group_stars} ở Mệnh thuộc {f.group} (Khảo Luận tr.166–167); đây là phân loại tính chất hoạt động của sao, chưa phải nhận định về số phận."]', '["KL pp.166-167"]', NULL);
INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('MT.10.FRAME', 'profiles', 8, '{"slot":"profiles","truthy":true}', 'sach', 'ground', '["Nền nghĩa của chính tinh ở Mệnh, theo Thực Hành: {profiles} ({profiles.cite})."]', '["{profiles.cite}"]', NULL);
