INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('VH.10.FRAME', 'dir', 0, NULL, 'tinh_toan', 'intro', '["Đại hạn trên lá số này chạy {dir}, bắt đầu từ cung Mệnh ở tuổi {start} theo {cuc}; mỗi chặng mười năm đi qua một cung, và năm {year} đương số {age} tuổi mụ."]', '[]', NULL);
