INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('VH.10.FRAME', 'method', 2, NULL, 'he_thong', 'method', '["Chương này chỉ dùng những câu đọc vận mà sách gắn với cung của từng chặng, cùng vị trí Tứ Hóa theo can của chặng; các câu sách nói về thành tựu sớm hay muộn đã được đọc trong từng chương theo cung, nên không nhắc lại ở đây."]', '[]', NULL);
