INSERT OR REPLACE INTO module_passages (module_id, passage_id, ord, when_json, basis, kind, variants_json, cites_json, layout_json) VALUES ('VH.20.NOW', 'where', 0, NULL, 'tinh_toan', 'timing', '["Từ {d.range} tuổi mụ, vận ở cung {d.palace} (can {d.stem}), {d.majors_phrase}{?d.domain|; cung này là nơi đọc {d.domain}}.","Chặng {d.range} tuổi mụ đi qua cung {d.palace}, can {d.stem}, {d.majors_phrase}{?d.domain|; đây là cung của {d.domain}}."]', '[]', NULL);
